/** 
 * CẤU HÌNH HỆ THỐNG MẶC ĐỊNH
 * Đã được cấu hình để chạy trực tiếp trên website của bạn
 */
const DEFAULT_API_URL = 'https://inabata.vn/ikvdevicemaster/api.php'; 
const DEFAULT_PROJECT_ID = 'ikv_device_master';

const LOCAL_STORAGE_KEY = 'device_master_encrypted';
const SETTINGS_KEY = 'device_master_settings';

const cryptoUtils = {
  deriveKey: async (password: string, salt: Uint8Array) => {
    const encoder = new TextEncoder();
    const baseKey = await crypto.subtle.importKey(
      'raw',
      encoder.encode(password),
      'PBKDF2',
      false,
      ['deriveKey']
    );
    return crypto.subtle.deriveKey(
      {
        name: 'PBKDF2',
        salt,
        iterations: 100000,
        hash: 'SHA-256'
      },
      baseKey,
      { name: 'AES-GCM', length: 256 },
      false,
      ['encrypt', 'decrypt']
    );
  },

  encrypt: async (data: string, password: string) => {
    const salt = crypto.getRandomValues(new Uint8Array(16));
    const iv = crypto.getRandomValues(new Uint8Array(12));
    const key = await cryptoUtils.deriveKey(password, salt);

    const encoder = new TextEncoder();
    const encrypted = await crypto.subtle.encrypt(
      { name: 'AES-GCM', iv },
      key,
      encoder.encode(data)
    );

    const combined = new Uint8Array(salt.length + iv.length + encrypted.byteLength);
    combined.set(salt, 0);
    combined.set(iv, salt.length);
    combined.set(new Uint8Array(encrypted), salt.length + iv.length);

    return btoa(String.fromCharCode(...combined));
  },

  decrypt: async (encryptedBase64: string, password: string) => {
    try {
      const combined = new Uint8Array(atob(encryptedBase64).split('').map(c => c.charCodeAt(0)));
      const salt = combined.slice(0, 16);
      const iv = combined.slice(16, 28);
      const data = combined.slice(28);

      const key = await cryptoUtils.deriveKey(password, salt);
      const decrypted = await crypto.subtle.decrypt(
        { name: 'AES-GCM', iv },
        key,
        data
      );

      return new TextDecoder().decode(decrypted);
    } catch (e) {
      throw new Error('Decryption failed');
    }
  }
};

export const storageService = {
  getSettings: () => {
    const settings = localStorage.getItem(SETTINGS_KEY);
    const parsed = settings ? JSON.parse(settings) : {};

    return {
      apiUrl: parsed.apiUrl || DEFAULT_API_URL,
      projectId: parsed.projectId || DEFAULT_PROJECT_ID
    };
  },

  saveSettings: (settings: { apiUrl: string, projectId: string }) => {
    localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));
  },

  saveDataSecure: async (devices: Device[], branches: string[], password: string): Promise<void> => {
    const payload: CloudPayload = {
      devices,
      branches,
      version: '2.0',
      updatedAt: new Date().toISOString()
    };
    const json = JSON.stringify(payload);
    const encrypted = await cryptoUtils.encrypt(json, password);
    localStorage.setItem(LOCAL_STORAGE_KEY, encrypted);
  },

  getDataSecure: async (password: string): Promise<CloudPayload> => {
    const encrypted = localStorage.getItem(LOCAL_STORAGE_KEY);
    if (!encrypted) return { devices: [], branches: ['Hồ Chí Minh', 'Đà Nẵng'], version: '2.0', updatedAt: '' };

    const decryptedJson = await cryptoUtils.decrypt(encrypted, password);
    const parsed = JSON.parse(decryptedJson);
    return parsed as CloudPayload;
  },

  syncWithMySQL: async (apiUrl: string, projectId: string, password: string, payload?: CloudPayload): Promise<CloudPayload | null> => {
    if (!apiUrl || !projectId) return null;
    try {
      if (payload) {
        const encryptedData = await cryptoUtils.encrypt(JSON.stringify(payload), password);
        const response = await fetch(apiUrl, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ project_id: projectId, payload: encryptedData }),
        });
        if (!response.ok) throw new Error('Upload failed');
        return payload;
      } 

      const response = await fetch(`${apiUrl}?project_id=${projectId}`);
      if (!response.ok) throw new Error('Download failed');

      const remoteData = await response.json();

      if (remoteData && remoteData.payload && remoteData.payload.trim() !== "") {
        const decrypted = await cryptoUtils.decrypt(remoteData.payload, password);
        return JSON.parse(decrypted) as CloudPayload;
      }
      return null;
    } catch (error) {
      console.error('MySQL Sync Error:', error);
      throw error;
    }
  },

  generateShareLink: (apiUrl: string, projectId: string) => {
    const baseUrl = window.location.origin + window.location.pathname;
    // Sử dụng encodeURIComponent để đảm bảo các ký tự như +, /, = không bị lỗi khi làm URL
    const config = encodeURIComponent(btoa(JSON.stringify({ a: apiUrl, p: projectId })));
    return `${baseUrl}?c=${config}`;
  },

  getConfigFromUrl: () => {
    const params = new URLSearchParams(window.location.search);
    let c = params.get('c');
    if (c) {
      try {
        // Thử giải mã URI trước (để xử lý link mới), nếu lỗi thì dùng nguyên gốc (để hỗ trợ link cũ)
        try { c = decodeURIComponent(c); } catch(e) {}

        const decoded = JSON.parse(atob(c));
        return { apiUrl: decoded.a, projectId: decoded.p };
      } catch (e) {
        console.error("Link config invalid:", e);
        return null;
      }
    }
    return null;
  },

  exportToCSV: (devices: Device[]) => {
    const headers = ['PC Name', 'Type', 'Branch', 'Manufacturer', 'Model', 'Serial', 'Purchase Date', 'Warranty Expiry', 'Handover Date', 'Assigned To', 'Status', 'Notes'];
    const rows = devices.map(d => [
      d.pcName || '',
      d.type,
      d.branch || '',
      d.manufacturer,
      d.model,
      d.serialNumber,
      d.purchaseDate,
      d.warrantyExpiry,
      d.handoverDate,
      d.assignedTo,
      d.status,
      d.notes || ''
    ]);
    const csvContent = [headers.join(','), ...rows.map(e => e.map(val => `"${val.toString().replace(/"/g, '""')}"`).join(','))].join('\n');
    const blob = new Blob(["\ufeff" + csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.setAttribute('href', URL.createObjectURL(blob));
    link.setAttribute('download', `devices_backup_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  },

  parseCSV: (csvText: string, defaultBranch: string = 'Hồ Chí Minh'): Device[] => {
    const lines = csvText.split(/\r?\n/);
    if (lines.length < 2) return [];
    const header = lines[0];
    const delimiter = header.includes(';') ? ';' : ',';
    const result: Device[] = [];
    for (let i = 1; i < lines.length; i++) {
      const line = lines[i].trim();
      if (!line) continue;
      const values: string[] = [];
      let current = '';
      let inQuotes = false;
      for (let char of line) {
        if (char === '"') inQuotes = !inQuotes;
        else if (char === delimiter && !inQuotes) { values.push(current.trim()); current = ''; }
        else current += char;
      }
      values.push(current.trim());
      if (values.length >= 5) {
        const clean = (val: string) => (val || '').replace(/^"|"$/g, '').trim();
        result.push({
          id: Math.random().toString(36).substr(2, 9),
          pcName: clean(values[0]),
          type: (clean(values[1]) || DeviceType.LAPTOP) as DeviceType,
          branch: clean(values[2]) || defaultBranch,
          manufacturer: clean(values[3]),
          model: clean(values[4]),
          serialNumber: clean(values[5]),
          purchaseDate: clean(values[6]),
          warrantyExpiry: clean(values[7]),
          handoverDate: clean(values[8]),
          assignedTo: clean(values[9]),
          status: (clean(values[10]) || 'Available') as any,
          notes: clean(values[11]),
          history: []
        });
      }
    }
    return result;
  }
};

